D[6315]={"^Creates a clone of an enemy player for (.-) which will deal (.-)%% of all damage it takes to the original target%.%s*$","Cria uma cópia de um jogador inimigo durante {{1}} que causará o {{2}}% de todo dano que recebe o alvo original."}
D[6368]={"^Share Chromie's wisdom with an allied player, increasing their Spirit by (.-)%. Lasts (.-)%.\n\nOnly one |cffffffffWisdom|r per Chronomancer can be active%.%s*$","Compartilha a sabedoria de Chromie com um jogador aliado, aumentando seu Espírito em {{1}}. Dura {{2}}.\n\nApenas um efeito de |cffffffffSabedoria|r por Cronomante pode estar ativo por vez."}
D[6799]={"^Unleash a wave of maddening resonance, interrupting the current spell cast of all enemies around you and preventing any spell in that school from being cast for (.-)%.%s*$","Desata uma onda de ressonância perturbadora, interrompendo o feitiço atual questão lançando todos os inimigos próximos evitando que possam lançar nenhum outro feitiço dessa escola durante {{1}}."}
D[6903]={"^Reverses gravity within (.-) yds, flinging all allied and enemy players into the air and allowing them to float for a short time%.\n\nAll enemies %(including non%-player enemies%) in the area are Interrupted, and prevented from casting any spells of the same school for (.-)%.%s*$","Inverte a gravidade em um raio de {{1}} m, lançando jogadores aliados e inimigos ao ar e permitindo que flutuem por um curto período.\n\nTodos inimigos na área, inclusive criaturas não controladas por jogadores, são interrompidos e ficam impedidos de lançar feitiços da mesma escola durante {{2}}."}
D[6907]={"^|cFFC49A6CContinuum Spell|r\nEmpower Wand attacks to affect up to (.-) additional nearby enemies for 3 sec plus (.-) sec per |cffffffffEcho Fragment|r%. \n\nAffected attacks deal less damage per additional enemy hit%.\n\nCan only have 1 |cFFC49A6CContinuum|r spell active at a time%.%s*$","|cFFC49A6CCenário Mágico|r\nPotencializa os ataques de varinha para afetar até {{1}} inimigos próximos adicionais durante 3 s mais {{2}} s para cada |cffffffffFragmento de Eco|r.\n\nOs ataques afetados causam menos dano para cada inimigo adicional alcançou.\n\nSó pode haver um máximo de 1 |cFFC49A6CCenário|r feitiço ativo por vez."}
