D[41200]={"^Blast an enemy and up to (.-) nearby enemies for (.-) Chromatic Damage%.\n\nGenerates 1 |cffffffffEcho Fragment|r%.%s*$","Golpeia um inimigo e até {{1}} inimigos próximos em {{2}} de dano CROMÁTICA.\n\nGera 1 |cffffffffFragmento de Eco|r."}
D[41201]={"^Blast an enemy and up to (.-) nearby enemies for (.-) Chromatic Damage%.%s*$","Golpeia um inimigo e até {{1}} inimigos próximos em {{2}} de dano CROMÁTICA."}
D[41202]={"^Deals (.-) Divine damage to an enemy and causes your next |cFFFFFFFFSandblast|r or |cFFFFFFFFUnmake|r within (.-) to hit 3 additional nearby targets%.\n\nThis spell belongs to |cFFFFFFFFOrder|r%.%s*$","Causa {{1}} de dano Divino a um inimigo e faz seu próximo |cFFFFFFFFRajada de Areia|r ou |cFFFFFFFFDesfazer|r, usado dentro de {{2}}, atingir 3 alvos próximos adicionais.\n\nEste feitiço pertence a |cFFFFFFFFOrdem|r."}
