D[42265]={"^Guarantees healing done by |cffffffffFabric of Time|r to critically strike and gives it an additional charge%.%s*$","Garante que a cura realizada por |cffffffffTecido do Tempo|r seja um acerto crítico e lhe dá uma carga adicional."}
D[42538]={"^Increases the all damage dealt by party and raid members by (.-)%%%. Does not stack with similar effects%.\n\nIn addition, your |cFFFFFFFFUnmake|r and |cFFFFFFFFTimerend|r gain an additional (.-)%% bonus spell scaling%.%s*$","Aumenta em {{1}}% todo o dano causado por membros do grupo e da raide. Não acumula com efeitos semelhantes.\n\nAlém disso, |cFFFFFFFFDesfazer|r e |cFFFFFFFFFim do Tempo|r recebem um bônus adicional de {{2}}% no escalonamento de feitiços."}
D[43011]={"^Transform into an |cFFFFFFFFIncarnate of Chaos|r, instantly resetting the cooldown of |cffffffffChromatic Shard|r and causing your next cast to not incur a cooldown%.\n\nIn addition, your damage dealt is increased by (.-)%% for (.-)%.%s*$","Transforma você em uma |cFFFFFFFFEncarnação do Caos|r, reiniciando instantaneamente a recarga de |cffffffffFragmento Cromático|r e fazendo com que sua próxima conjuração não entre em recarga.\n\nAlém disso, seu dano causado aumenta em {{1}}% durante {{2}}."}
D[43125]={"^Share Nozdormu's Wisdom with an allied player, increasing their Intellect by (.-) for (.-)%.\n\nOnly one |cffffffffWisdom|r per Chronomancer can be active%.%s*$","Compartilha a Sabedoria de Nozdormu com um aliado, aumenta seu Intelecto em {{1}} durante {{2}}.\n\nSó pode ter uma |cffffffffSabedoria|r por vez para cada Cronomante."}
D[43283]={"^Reduces the cast time of |cFFFFFFFFArtificer's Wand|r by (.-)%% and reduces the mana cost of your instant spells by (.-)%%%.%s*$","Reduz o tempo de lançamento de |cFFFFFFFFVarinha do Artífice|r em {{1}}% e reduz o custo de mana de seus feitiços instantâneos em {{2}}%."}
D[43284]={"^Reduces the cast time of |cFFFFFFFFUnmake|r by (.-)%% and reduces the mana cost of your instant spells by (.-)%%%.%s*$","Reduz o tempo de lançamento de |cFFFFFFFFDesfazer|r em {{1}}% e reduz o custo de mana de seus feitiços instantâneos em {{2}}%."}
D[43366]={"^Heals up to (.-) allies for (.-)%.%s*$","Cura até {{1}} aliados em {{2}}."}
D[43385]={"^Casting |cffffffffMelt Reality|r now refreshes a charge of |cffffffffChronostasis|r%.%s*$","Lançar |cffffffffDerretir a Realidade|r agora restaura uma carga de |cffffffffCronostase|r."}
D[43403]={"^While |cffffffffIncarnation of Chaos|r is active, your |cffffffffMelt Reality|r deals (.-)%% increased damage and replicates an additional (.-)%% \n\nIn addition, periodic damage dealt now has a (.-)%% chance to reduce the cooldown of |cffffffffIncarnation of Chaos|r by (.-) sec%.%s*$","Enquanto estiver ativo o |cffffffffEncarnação do Caos|r, seu |cffffffffDerretir a Realidade|r causa dano aumentado em {{1}}% e replica mais {{2}}%\n\nAlém disso, agora o dano periódico tem uma chance adicional de {{3}}% de reduz a recarga de |cffffffffEncarnação do Caos|r em {{4}} s."}
D[43405]={"^Your |cfffffffffTimerend|r now strikes 4 additional nearby enemies%.%s*$","Seu |cffffffffFim do Tempo|r agora atinge 4 inimigos próximos adicionais."}
D[43408]={"^While |cffffffffIncarnation of Chaos|r is active, your |cffffffffMelt Reality|r deals (.-)%% increased damage and strikes up to (.-) additional nearby enemies%.\n\nIn addition, periodic damage dealt now has a (.-)%% chance to reduce the cooldown of |cffffffffIncarnation of Chaos|r by 0%.5 sec%.%s*$","Enquanto |cffffffffEncarnação do Caos|r estiver ativa, |cffffffffDerretir a Realidade|r causa {{1}}% a mais de dano e atinge até {{2}} inimigos próximos adicionais.\n\nAlém disso, seu dano periódico tem {{3}}% de chance de reduzir em 0,5 s a recarga de |cffffffffEncarnação do Caos|r."}
D[43415]={"^Increases the damage of |cffffffffDecomposition|r and |cffffffffUnmake|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffDecomposição|r e |cffffffffDesfazer|r em {{1}}%."}
D[43636]={"^Casting |cffffffffUnmake|r now increases your critical strike chance by (.-)%% and the damage of |cFFFFFFFFChromatic Spike|r by (.-)%% for (.-), stacking (.-) times%.%s*$","Lançar |cffffffffDesfazer|r agora aumenta em {{1}}% sua chance de acerto crítico e em {{2}}% o dano de |cFFFFFFFFEspinho Cromático|r por {{3}}, acumulando até {{4}} vezes."}
D[44192]={"^Casting |cFFFFFFFFMelt Reality|r now causes your next |cffffffffUnmake|r or |cffffffffReverse Wound|r within (.-) to become instant and cost (.-)%% less mana%.%s*$","Lançar |cFFFFFFFFDerretir a Realidade|r faz com que seu próximo |cffffffffDesfazer|r ou |cffffffffReverter Ferimento|r usado nos próximos {{1}} seja instantâneo e custe {{2}}% menos mana."}
D[44811]={"^Reduces the cooldown of |cFFFFFFFFRune of Resonance|r by (.-) sec and |cffffffffTurbulence|r by (.-) sec%.\n\nAdditionally, |cFFFFFFFFRune of Resonance|r now deals (.-)%% increased damage if it hits at least (.-) enemies%.%s*$","Reduz a recarga de |cFFFFFFFFRuna de Ressonância|r em {{1}} s e de |cffffffffTurbulência|r em {{2}} s.\n\nAlém disso, |cFFFFFFFFRuna de Ressonância|r agora causa um aumento de {{3}}% se golpeia a ao menos {{4}} inimigos."}
D[44864]={"^Increases the critical strike chance of your |cffffffffReverse Wound|r, |cFFFFFFFFEpoch|r, and |cFFFFFFFFCorrect the Mistake|r by (.-)%%%.%s*$","Aumenta a chance de acerto crítico de seu |cffffffffReverter Ferimento|r, |cFFFFFFFFÉpoca|r e |cFFFFFFFFCorrigir o Erro|r em {{1}}%."}
D[44956]={"^Marks an enemy's location, yanking them back to the location after (.-)%.%s*$","Marca a localização de um inimigo, tirando dele até essa localização depois de {{1}}."}
D[45196]={"^Reduces the cooldown of |cffffffffTimerend|r by (.-) sec and increases the duration of |cffffffffDecomposition|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffFim do Tempo|r em {{1}} s. e aumenta a duração de |cffffffffDecomposição|r em {{2}} s."}
D[45357]={"^Damage dealt by |cffffffffUnmake|r now slows the target's movement speed by 5%% for (.-), stacking (.-) times%.%s*$","O dano causado por |cffffffffDesfazer|r agora desacelera a velocidade de movimento do alvo em 5% durante {{1}}, acumulando-se {{2}} vezes."}
D[46859]={"^Every time you cast a Chromatic or Order spell, you will gain a Chromatic Charge or Order Charge respectively%.\n\nUpon reaching 4 charges of any kind, you will perform an additional effect based on the combination of charges%.\n\nOrder %+ Order %+ Order %+ Order = Add 3 stacks of Accelerated Recovery to party and raid members within 40 yards%.\n\nOrder %+ Order %+ Order %+ Chromatic = Gain Hasten, Spell Deflection, and Time Loop%.\n\nOrder %+ Order %+ Chromatic %+ Chromatic = Restore 30%% of your maximum |cff01cdfeMana|r and 20%% of your Maximum |cfffeff9eHealth|r%.\n\nThen, |cfffeff9eSummon|r an Infinite Clone%.\n\nChromatic %+ Chromatic %+ Chromatic %+ Order = Launch 3 Epochs at your current target%.\n\nChromatic %+ Chromatic %+ Chromatic %+ Chromatic = Advance all stacks of Decomposition on nearby enemies by 3%.%s*$","Sempre que você lança um feitiço Cromático ou de Ordem, recebe uma Carga Cromática ou uma Carga de Ordem, respectivamente.\n\nAo atingir 4 cargas de qualquer tipo, um efeito adicional é ativado conforme a combinação:\n\nOrdem + Ordem + Ordem + Ordem = Adiciona 3 acúmulos de Recuperação Acelerada aos membros do grupo e da raide em um raio de 40 m.\n\nOrdem + Ordem + Ordem + Cromático = Concede Célere, Desvio de Feitiços e Ciclo Temporal.\n\nOrdem + Ordem + Cromático + Cromático = Restaura 30% da sua |cff01cdfeMana|r máxima e 20% da sua |cfffeff9eVida|r máxima.\n\nEm seguida, |cfffeff9eEvocar|r um Clone Infinito.\n\nCromático + Cromático + Cromático + Ordem = Lança 3 Épocas contra o alvo atual.\n\nCromático + Cromático + Cromático + Cromático = Avança em 3 todos os acúmulos de Decomposição nos inimigos próximos."}
D[46861]={"^You place a time loop on the target ally%. The next spell or ability they use within 7 seconds %(that has a resource cost or a cast time%) will instantly trigger an additional 2 times%.%s*$","Aplica um |cffffffffCiclo Temporal|r ao aliado selecionado. O próximo feitiço ou habilidade que ele usar dentro de 7 s, desde que tenha custo de recurso ou tempo de lançamento, será acionado instantaneamente mais 2 vezes."}
D[46862]={"^You embrace the chaotic nature of the universe%.Chaos Shard will now apply 1 stack of Decomposition, and will have a chance to grant you Time Loop%.When Age deals damage, it has a chance to reset the cooldown of Chaos Shard%.Whenever a Gravity Bomb explodes, reset the cooldown of Epoch and Timerend%.Whenever Decomposition deals damage it will have a chance to reset the cooldown of Epoch or Chaos Shard%.%s*$","Você abraça a natureza caótica do universo. Fragmento do Caos agora aplica 1 acúmulo de Decomposição e tem chance de conceder Ciclo Temporal. Quando Idade causa dano, tem chance de reiniciar a recarga de Fragmento do Caos. Sempre que uma Bomba Gravitacional explode, as recargas de Época e Fim do Tempo são reiniciadas. Sempre que Decomposição causa dano, tem chance de reiniciar a recarga de Época ou Fragmento do Caos."}
D[46866]={"^Increases periodic damage taken from the Chronomancer by (.-)%% for (.-), stacking (.-) times%.%s*$","Aumenta o dano periódico recebido Cronomante em {{1}}% durante {{2}}, acumulando-se {{3}} vezes."}
D[47435]={"^Launch a blast of magical sand, dealing (.-) Arcane Damage to up to (.-) enemies within (.-) yds of the target%.\n\nThis spell belongs to |cffffffffOrder|r%.\n\nThe next time the primary target receives damage, allies within (.-) yds are healed for (.-)%% maximum health%.%s*$","Lança uma rajada de areia mágica, causando {{1}} de dano Arcano a até {{2}} inimigos em um raio de {{3}} m do alvo.\n\nEste feitiço pertence a |cffffffffOrdem|r.\n\nNa próxima vez que o alvo principal receber dano, aliados em um raio de {{4}} m recuperam {{5}}% da vida máxima."}
D[47436]={"^Launch a blast of magical sand, dealing (.-) Arcane Damage to up to (.-) enemies within (.-) yds of the target%.\n\nThis spell belongs to |cffffffffOrder|r%.%s*$","Lança uma rajada de areia mágica, causando {{1}} de dano Arcano a até {{2}} inimigos dentro de {{3}} m do alvo.\n\nEste feitiço pertence a |cffffffffOrdem|r."}
D[47437]={"^Launch a blast of magical sand, dealing (.-) Arcane Damage to up to (.-) enemies within (.-) yds of the target%.\n\nThe next time the primary target receives damage, allies within (.-) yds are healed for (.-)%% maximum health%.%s*$","Lança uma rajada de areia mágica, causando {{1}} de dano Arcano a até {{2}} inimigos em um raio de {{3}} m do alvo.\n\nNa próxima vez que o alvo principal receber dano, aliados em um raio de {{4}} m recuperam {{5}}% da vida máxima."}
D[47438]={"^Launch a blast of magical sand, dealing (.-) Arcane Damage to up to (.-) enemies within (.-) yds of the target%.%s*$","Lança uma rajada de areia mágica, causando {{1}} de dano Arcano a até {{2}} inimigos dentro de {{3}} m do alvo."}
D[47561]={"^Redirects (.-)%% damage taken from the caster to the pet  for (.-)%.%s*$","Redireciona {{1}}% do dano recebido pelo conjurador à mascote durante {{2}}."}
D[47713]={"^|cffffffffWand of Time|r and |cffffffffShatter Echo|r now have a (.-)%% chance to unleash |cFFFFFFFFCrystal Cannon|r, launching 2 quick lesser Wand auto attacks at the enemy over (.-), scaling with Spirit%.\n\nWhile |cffffffffParadox Cannon|r is active, the chance to trigger this effect is increased by (.-)%%%.%s*$","|cffffffffVarinha do Tempo|r e |cffffffffEstilhaçar Eco|r agora têm {{1}}% de chance de liberar |cFFFFFFFFCanhão de Cristal|r, desferindo 2 ataques automáticos menores e rápidos com a varinha contra o inimigo ao longo de {{2}}, com escala baseada no Espírito.\n\nEnquanto |cffffffffCanhão Paradoxal|r estiver ativo, a chance de ativar este efeito aumenta em {{3}}%."}
D[47856]={"^Fire a blast of enchanted sand at an enemy, dealing (.-) Arcane Damage and granting |cffffffffSands of Time|r%.\n\n\nThis spell belongs to |cFFFFFFFFOrder|r%.%s*$","Lança um jato de arena encantado um inimigo, causando {{1}} de dano Arcano e concedendo |cffffffffAreias do Tempo|r.\n\nEste feitiço pertence a |cFFFFFFFFOrdem|r."}
D[47857]={"^Fire a blast of enchanted sand at an enemy, dealing (.-) Arcane Damage and granting |cffffffffSands of Time|r%.%s*$","Lança uma rajada de arena encantado contra um inimigo, causando {{1}} de dano Arcano e concedendo |cffffffffAreias do Tempo|r."}
D[48041]={"^While |cffffffffIncarnation of Chaos|r is active, all damage dealt now has a (.-)%% chance to lock yourself in a time loop for (.-), making you unable to cast any spells other than |cFFFFFFFFChromatic Shard|r%.\n\nWhile active, you cast |cFFFFFFFFChromatic Shard|r free of cost, repeating every (.-) sec%.%s*$","Enquanto |cffffffffEncarnação do Caos|r estiver ativa, todo dano causado terá {{1}}% de chance de prender você em um ciclo temporal por {{2}}, impedindo-o de lançar qualquer feitiço que não seja |cFFFFFFFFFragmento Cromático|r.\n\nDurante o ciclo, você lança |cFFFFFFFFFragmento Cromático|r sem custo, repetindo o lançamento a cada {{3}} s."}
D[48042]={"^While |cffffffffIncarnation of Chaos|r is active, you may now cast |cffffffffChromatic Shard|r while moving, but the duration of |cffffffffIncarnation of Chaos|r is reduced by (.-) sec%.%s*$","Enquanto |cffffffffEncarnação do Caos|r está ativa, agora pode lançar |cffffffffFragmento Cromático|r enquanto se movimenta, mas a duração de |cffffffffEncarnação do Caos|r é reduzido em {{1}} s."}
D[48686]={"^Tuning aura for Chronomancer Class%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste da classe Cronomante. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48729]={"^Tuning aura for Chronomancer %- Infinite%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste de Cronomante — Infinito. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48730]={"^Tuning aura for Chronomancer %- Time%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste de Cronomante — Tempo. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48731]={"^Tuning aura for Chronomancer %- Artificer%. Modifies damage dealt, damage taken, and healing done%.%s*$","Aura de ajuste de Cronomante — Artífice. Modifica o dano causado, o dano recebido e a cura realizada."}
D[48797]={"^Deals (.-) Arcane damage to nearby enemies, and then redirects (.-)%% of all damage taken by the Chronomancer to the Bronze Protector for (.-)%.%s*$","Causa {{1}} de dano Arcano aos inimigos próximos e, em seguida, redireciona {{2}}% de todo o dano recebido pelo Cronomante para o Protetor de Bronze durante {{3}}."}
D[50313]={"^Reduces the cast time of your next direct damage spell except Temporal Blast by 40%%%. Can hold up to 3 charges and lasts (.-)%.\n\nReaching 3 stacks of |cFFFFFFFFTemporal Haste|r will trigger a temporally charged Lunar Eclipse %(if known%)%. This Lunar Eclipse is just as powerful as normal one, but expires three times faster%.%s*$","Reduz o tempo de lançamento de seu próximo feitiço de dano direto (exceto Explosão temporal) em 40%.\nPode acumular até 3 cargas e dura {{1}}.\n\nAo alcançar 3 acúmulos de |cFFFFFFFFAceleração Temporal|r, será ativado uma eclipses lunar carregada temporariamente (se você conhece o feitiço). Esta eclipses lunar é tão poderosa como a normal, mas expira três vezes mais rápido."}
D[51867]={"^You learn to bend time in your favor%. \n\nYou learn |cFFFFFFFFTemporal Blast|r%. \n\nLunar Eclipse increases damage of your Starfire, Starsurge and Moonfire by (.-)%%%.%s*$","Aprende a dobrar o tempo a seu favor.\n\nAprende |cFFFFFFFFExplosão Temporal|r.\n\nEclipse Lunar Cheia aumenta o dano de seu Fogo Estelar, Surto Estelar e Fogo lunar em {{1}}%."}
D[51868]={"^You learn to bend time in your favor%. \n\nYou learn |cFFFFFFFFTemporal Blast|r%. \n\nLunar Eclipse increases damage of your Starfire, Starsurge and Moonfire by (.-)%%%. %((.-)%% versus players%)%.%s*$","Aprende a dobrar o tempo a seu favor.\n\nAprende |cFFFFFFFFExplosão Temporal|r.\n\nEclipse Lunar Cheia aumenta o dano de seu Fogo Estelar, Surto Estelar e Fogo lunar em {{1}}%. ({{2}}% contra jogadores)."}
D[53170]={"^Upon reaching 4 stacks, consume all |cFFFFFFFFPotential|r stacks and gain |cFFFFFFFFElemental Resonance|r based on which |cFFFFFFFFElemental Mote|r you have in the cycle%.%s*$","Ao atingir 4 acúmulos, consome todos os acúmulos de |cFFFFFFFFPotencial|r e concede |cFFFFFFFFRessonância Elemental|r de acordo com o |cFFFFFFFFPartícula Elemental|r atual do ciclo."}
D[53208]={"^Resonances grant (.-)%% increased school spell critical strike chance and varying amounts of school damage depending on the Resonance, reduced by half against players%.\n\n|cFF8A2BE2Arcane|r: (.-)%% increased Arcane damage%.\n|cFFFF0000Fire|r: (.-)%% increased Fire damage%.\n|cFF0000FFFrost|r: (.-)%% increased Frost damage%.\n|cFF00FF00Nature|r: (.-)%% increased Nature damage%.\n\nAdditionally, they reduce the damage of all other elements by (.-)%%%.%s*$","As resonâncias concedem um aumento em {{1}}% na chance de acerto crítico com feitiços descola e dano variável conforme a Ressonância, reduzidos à metade contra jogadores.\n\n|cFF8A2BE2Arcano|r: Aumento de {{2}}% no dano Arcano.\n|cFFFF0000Fogo|r: Aumento do {{3}}% no dano de Fogo.\n|cFF0000FFGelo|r: Aumento do {{4}}% no dano de Gelo.\n|cFF00FF00Natureza|r: Aumento do {{5}}% no dano de Natureza.\n\nAlém disso, reduzem o dano de todos mais elementos em {{6}}%."}
D[53209]={"^Resonances grant (.-)%% increased school spell critical strike chance and varying amounts of school damage depending on the Resonance, reduced by half against players%.\n\n|cFF8A2BE2Arcane|r: (.-)%% increased Arcane damage%.\n|cFFFF0000Fire|r: (.-)%% increased Fire damage%.\n|cFF0000FFFrost|r: (.-)%% increased Frost damage%.\n|cFF00FF00Nature|r: (.-)%% increased Nature damage%.\n\nAdditionally, they reduce the damage of all other elements by (.-)%%%.\n\nWhen the Resonance ends, it resets the Meteor internal cooldown of the corresponding element%.%s*$","As Ressonâncias concedem {{1}}% de chance adicional de acerto crítico com feitiços da escola correspondente e aumentam o dano dessa escola de acordo com a Ressonância. Os bônus são reduzidos pela metade contra jogadores.\n\n|cFF8A2BE2Arcano|r: {{2}}% de dano Arcano adicional.\n|cFFFF0000Fogo|r: {{3}}% de dano de Fogo adicional.\n|cFF0000FFGelo|r: {{4}}% de dano de Gelo adicional.\n|cFF00FF00Natureza|r: {{5}}% de dano de Natureza adicional.\n\nAlém disso, reduzem em {{6}}% o dano de todos os outros elementos.\n\nQuando a Ressonância termina, reinicia a recarga interna do Meteorito do elemento correspondente."}
D[54571]={"^Arcane Blast no longer increases damage and mana cost and instead increases your healing done by 3%% per stack%.\n\nYour Arcane Resonance now generates a stack of Arcane Blast every 6 seconds%.%s*$","Impacto Arcano não aumenta o dano nem o custo de mana, mas agora aumenta sua cura em 3% por acúmulo.\n\nSua Ressonância Arcana gera agora um acúmulo de Impacto Arcano a cada 6 segundos."}
D[54572]={"^Arcane Blast no longer increases damage and mana cost and instead increases your healing done by 6%% per stack%.\n\nYour Arcane Resonance now generates a stack of Arcane Blast every 3 seconds%.%s*$","Impacto Arcano não aumenta o dano nem o custo de mana, mas agora aumenta sua cura em 6% por acúmulo.\n\nSua Ressonância Arcana gera agora um acúmulo de Impacto Arcano a cada 3 segundos."}
D[54644]={"^Heals all nearby Aligned or Time%-bound targets every second for 4 seconds%. While channelling, time is stalled and freezes the duration of active Aligns%.%s*$","cura todos os alvos Alinhados ou Limitados pelo Tempo próximos a cada segundo durante 4 segundos. Enquanto é canalizada, o tempo se detém e congela a duração dos Alinhamentos ativos."}
