T[14348]={"^%$%?s706062%[Damage from the Chronomancer increased by (.-)%%%.\n\n%]%[%]After (.-) sec, you explode for (.-) Shadow damage and pull your allies toward you%.%s*$","$?s706062[O dano do Cronomante aumenta em {{1}}%.\n\n][]Após {{2}} s, você explode, causando {{3}} de dano de Sombra e puxando seus aliados em sua direção."}
T[14358]={"^Reduces the cast time of Chromatic Shard by (.-)%%%$%?s503831%[ and increases its damage and critical strike chance by (.-)%%%]%[%]%. Stacks (.-) times%.%s*$","Reduz o tempo de lançamento de Estilhaço Cromático em {{1}}%$?s503831[ e aumenta seu dano e sua chance de acerto crítico em {{2}}%][]. Acumula até {{3}} vezes."}
T[14405]={"^At 3 stacks, you transform your Bronze Protector into a Bronze Dragonkin for (.-)%.%s*$","Ao atingir 3 acúmulos, seu |cffffffffProtetor de Bronze|r se transforma em um Draconiano de Bronze durante {{1}}."}
T[14448]={"^Primary attributes reduced by (.-)%%%$%?s704490%[ Periodic damage taken by the Chronomancer increased by (.-)%%%.%]%[%] Stacks (.-) times%.%s*$","Atributos primários reduzidos em {{1}}%$?s704490[. O dano periódico do Cronomante recebido aumenta em {{2}}%.][]. Acumula até {{3}} vezes."}
T[14482]={"^At 3 stacks, your next |cFFFFFFFFWand of Time|r or |cFFFFFFFFArtificer's Wand|r causes an additional (.-) Arcane Damage, scaling with Spirit%.%s*$","Ao atingir 3 acúmulos, seu próximo |cFFFFFFFFVarinha do Tempo|r ou |cFFFFFFFFVarinha do Artífice|r causa {{1}} de dano Arcano adicional, escalando com Espírito."}
T[14495]={"^For each stack of Chromatic above 10, Chronobeam will launch a Chromatic Shard at the target%. \n\nEach tick causes (.-) Chromatic Damage and generates 1 Order%.%s*$","Para cada acúmulo de Cromático acima de 10, Raio Cronal lança um Fragmento Cromático no alvo.\n\nCada pulso causa {{1}} de dano Cromático e gera 1 Ordem."}
T[14663]={"^Reduces the cast time of |cffffffffReverse Wound|r by 0%.25 sec%.%s*$","Reduz o tempo de lançamento do |cffffffffReverter Ferimento|r em 0.25 s."}
T[14664]={"^Your next Chronurgy is instant cast%.%s*$","Sua próxima |cffffffffCronurgia|r é lançada instantaneamente."}
T[14665]={"^Your next Discordance is instant cast%.%s*$","Sua próxima |cffffffffDiscordância|r é lançada instantaneamente."}
T[14666]={"^Reduces the cooldown of |cffffffffGravity Bomb|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffBomba Gravitacional|r em {{1}} s."}
T[14667]={"^Reduces the cooldown of |cffffffffGravity Bomb|r by (.-) sec, and the explosion occurs 3 sec faster%.%s*$","Reduz a recarga de |cffffffffBomba Gravitacional|r em {{1}} s e a explosão acontece 3 s antes."}
T[14670]={"^Reduces the cooldown of |cffffffffPast Self|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffEu do passado|r em {{1}} s."}
T[14674]={"^|cFFFFFFFFWand of Time|r now applies |cFFFFFFFFSplitting Time|r to the enemy%.%s*$","|cFFFFFFFFVarinha do Tempo|r agora aplica |cFFFFFFFFDivisão do Tempo|r o inimigo."}
T[14675]={"^Reduces magic damage taken by (.-)%% and causes taking damage to increase your movement speed by (.-)%% for (.-)%.\n\nThis can occur only once every 10 seconds%.%s*$","Reduz o dano mágico recebido em {{1}}% e faz com que receber dano aumente sua velocidade de movimento em {{2}}% durante {{3}}.\n\nIsto pode acontecer Apenas uma vez a cada 10 segundos."}
T[14796]={"^Damage from the Chronomancer increased by (.-)%%%.\n\nAfter (.-) sec, you explode for (.-) Chromatic Damage and pull your allies toward you%.%s*$","Dano do Cronomante aumenta em {{1}}%.\n\nDepois de {{2}} s, explode causando {{3}} Dano Cromática e você se move cima seus aliados."}
T[14797]={"^After (.-) sec, you explode for (.-) Chromatic Damage and pull your allies toward you%.%s*$","Depois de {{1}} s, explode causando {{2}} Dano Cromática e você se move cima seus aliados."}
T[14909]={"^Wand attacks cause additional Arcane damage%.%s*$","Os ataques com varinha causam dano Arcano adicional."}
T[14911]={"^Healing for (.-) every (.-) sec%. Healing received increased by 10%%%.%s*$","Cura {{1}} a cada {{2}} s. A cura recebida aumenta em 10%."}
T[14912]={"^The ticks of your periodic damaging and healing effects have a chance to boost the Quickness of your next Chronobeam spell by (.-)%%, stacks up to 4 times%.%s*$","As pulsações dos seus efeitos periódicos de dano e cura têm uma chance de aumentar em {{1}}% a Rapidez do seu próximo Raio Cronal, acumulando até 4 vezes."}
T[15004]={"^Generating 1 Echo Fragment every (.-) sec%.%s*$","Gera 1 Fragmento Eco a cada {{1}} s."}
T[15007]={"^Reduces |cffffffffEpoch|r's healing by (.-)%%, but causes it to heal for an additional 50%% of the amount healed over (.-)%.%s*$","Reduz a cura de |cffffffffÉpoca|r em {{1}}%, mas Faz com que cure uma quantidade adicional de 50% do valor curado sobre {{2}}."}
T[15008]={"^Increases |cffffffffEpoch|r's cast time by (.-)%%, healing done by (.-)%%, and causes it to apply a damage absorption shield equal to 30%% of the amount healed for (.-)%.%s*$","Aumenta o tempo de lançamento de |cffffffffÉpoca|r em {{1}}%, a cura realizada em {{2}}%, e faz com que aplique um escudo de absorção de dano equivalente de 30% do valor curado durante {{3}}."}
T[15010]={"^Causes wand attacks to grant |cffffffffSands of Time|r%.%s*$","Faz com que os ataques de varinha concedam |cffffffffAreias do Tempo|r."}
T[15605]={"^Turns the world upside down%.%s*$","Voltear o mundo ao revés."}
T[15606]={"^The gravity in the room is suspended%.%s*$","A gravidade na habitação se seuspende."}
T[15674]={"^You feel very light%.%.%.%s*$","Te sente muito leve..."}
T[15820]={"^Reflects damage dealt to Simon onto the Reflection inside%.%s*$","Reflete o dano causado a Simon até a Reflexão dentro."}
T[15821]={"^Causes the Reflection and his owner to swap position%.%s*$","Faz com que a Reflexão e seu dono intermudem posições."}
T[15822]={"^Inflicts Arcane damage based on the damage taken by your reflection%.%s*$","Causa dano Arcano baseado no dano recebido por seu reflexão."}
T[16506]={"^Attack and spell haste increased by 50%%%.\nApplying Time Lapse every second%.\nThe damage increase is multiplicative%.%s*$","A aceleração de ataques e feitiços aumenta em 50%.\nAplica |cffffffffLapso de Tempo|r a cada segundo.\nO aumento de dano é multiplicativo."}
T[17252]={"^Reduces the cast time of your next direct damage spell except Arcane Blast by (.-)%%%.%s*$","Reduz o tempo de lançamento de seu próximo feitiço de dano direto, exceto Impacto Arcano, em {{1}}%."}
T[17253]={"^Storing cast time%. If you cancel your cast, the cast time of you next Temporal Blast will be reduced%.%s*$","Armazena tempo de lançamento. Se você cancelar o lançamento, o tempo de lançamento da sua próxima Explosão Temporal será reduzido."}
T[18266]={"^The guards are protecting Chronicler Harvey at all costs%. All damage suffered by the Chronicler is redirected to his guards%.%s*$","Os guardas estão protegendo ao Cronista Harvey a toda costa. Todo o dano sofrido pelo Cronista é redirecionado a seus guardas."}
T[18296]={"^Time is running%.%.%.%s*$","O tempo se acaba."}
T[19666]={"^Reduces the cast time of your next direct damage spell except Temporal Blast by 40%%%.%s*$","Reduzir o tempo de lançamento de seu próximo feitiço de dano direto exceto Explosão Temporal em 40%."}
T[21122]={"^Damage of your next Arcane Blast increased by (.-)%% and the number of the Arcane Blast stacks it generates increased by (.-)%.\n\nYour next Spellsteal steals (.-) additional magic effect%.\n\nLasts (.-)%. Stacks up to (.-)%.%s*$","O dano do próximo Impacto Arcano aumenta em {{1}}% e o número de acúmulos que gera aumenta em {{2}}.\n\nSeu próximo Roubo Mágico rouba {{3}} efeito mágico adicional.\n\nDura {{4}}. Acumula até {{5}}."}
T[21757]={"^(.-)%% chance to reflect spells%.%s*$","{{1}}% de chance de refletir feitiços."}
T[22737]={"^Nature damage taken increased by (.-)%%%.%s*$","O dano de Natureza recebido aumenta em {{1}}%."}
T[23116]={"^Redirecting threat%.%s*$","Redirecionando ameaça."}
T[23117]={"^You feel lighter%.%.%.%s*$","Te sente mais leve."}
T[25245]={"^Will explode, causing damage to nearby allies, pulling them to you after (.-) sec%.%s*$","Explodirá, causando dano aos aliados próximos e arrastando-os contra você após {{1}} s."}
T[25343]={"^Damage dealt increased by (.-)%%%.%s*$","O dano causado aumenta em {{1}}%."}
